  CONSTRAINT `transactions_ibfk_1` FOREIGN KEY (`account_id`) REFERENCES `accounts` (`id`),
  CONSTRAINT `transactions_ibfk_2` FOREIGN KEY (`bank_account_id`) REFERENCES `bank_accounts` (`id`),
  CONSTRAINT `transactions_ibfk_3` FOREIGN KEY (`upload_id`) REFERENCES `uploads` (`id`),
  CONSTRAINT `transactions_ibfk_4` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `transactions_ibfk_5` FOREIGN KEY (`message_id`) REFERENCES `messages` (`id`),
  CONSTRAINT `ck_transactions_source` CHECK ((`source` in (_utf8mb4'IMAGE',_utf8mb4'MANUAL',_utf8mb4'REVERT'))),
  CONSTRAINT `ck_transactions_status` CHECK ((`status` in (_utf8mb4'VERIFIED',_utf8mb4'REVERTED'))),
  CONSTRAINT `ck_transactions_type` CHECK ((`type` in (_utf8mb4'CREDIT',_utf8mb4'DEBIT',_utf8mb4'REVERT')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
